input.content:
{
  "schema": "recall-coach.bank.v1",
  "license": "本项目原创题目，仅供本次比赛作品使用",
  "note": "固定内置题库，不依赖任何外部模型服务，不声称动态 AI 出题。",
  "modules": [
    {"id": "tx-acid", "name": "事务与ACID", "summary": "原子性、一致性、隔离性、持久化的含义与边界"},
    {"id": "tx-isolation", "name": "隔离级别与并发异常", "summary": "脏读、不可重复读、幻读与四种标准隔离级别"},
    {"id": "mvcc", "name": "多版本并发控制", "summary": "快照读、当前读、ReadView 与回滚版本链"},
    {"id": "idx-btree", "name": "索引结构", "summary": "B+树特性、聚簇与二级索引、回表、最左前缀"},
    {"id": "idx-perf", "name": "索引与执行计划", "summary": "选择性、覆盖索引、索引失效场景与代价"},
    {"id": "lock", "name": "锁与死锁", "summary": "行锁、间隙锁、锁等待与死锁处理"},
    {"id": "recovery", "name": "日志与崩溃恢复", "summary": "redo/undo 日志、WAL、检查点与恢复流程"},
    {"id": "storage", "name": "存储引擎与分布式", "summary": "LSM 树、读写放大、分区与租户资源隔离"}
  ],
  "questions": [
    {
      "id": "tx-acid-1", "module": "tx-acid", "difficulty": 1,
      "stem": "事务执行到一半时进程崩溃，已经修改的数据在重启后要么全部生效、要么全部不生效。这主要体现了 ACID 中的哪一项？",
      "options": [
        {"key": "A", "text": "原子性（Atomicity）"},
        {"key": "B", "text": "一致性（Consistency）"},
        {"key": "C", "text": "隔离性（Isolation）"},
        {"key": "D", "text": "持久性（Durability）"}
      ],
      "answer": "A",
      "explain": "原子性要求事务是不可分割的工作单元，提交前失败必须整体回滚。持久性说的是已提交事务在掉电后不丢失，二者常被混淆。"
    },
    {
      "id": "tx-acid-2", "module": "tx-acid", "difficulty": 2,
      "stem": "关于持久性（Durability），下列说法最准确的是？",
      "options": [
        {"key": "A", "text": "只要数据页写入了缓冲池，事务就永久安全"},
        {"key": "B", "text": "事务返回提交成功后，其修改在故障后仍能通过日志恢复出来"},
        {"key": "C", "text": "持久性只由操作系统的文件缓存保证，与数据库无关"},
        {"key": "D", "text": "持久性与提交协议无关，只取决于磁盘速度"}
      ],
      "answer": "B",
      "explain": "提交的语义是重做日志已按提交协议落盘，数据页可以稍后刷盘。缓冲池未落盘、仅靠页缓存都不能算持久。"
    },
    {
      "id": "tx-acid-3", "module": "tx-acid", "difficulty": 3,
      "stem": "某转账业务要求账户总额不变，开发者在应用层加了校验，但数据库仍出现了总额为负的中间状态被别的会话读到。对“一致性”最合理的理解是？",
      "options": [
        {"key": "A", "text": "一致性由数据库自动保证，无需业务参与"},
        {"key": "B", "text": "一致性指事务前后数据满足业务约束，需要约束、触发器或业务逻辑共同保证"},
        {"key": "C", "text": "只要提高隔离级别就一定能保证业务约束"},
        {"key": "D", "text": "一致性等同于日志的顺序写入"}
      ],
      "answer": "B",
