:root {
  --ink: #14181f;
  --ink-2: #39424f;
  --muted: #6b7688;
  --line: #e2e6ee;
  --bg: #f4f6fa;
  --card: #ffffff;
  --brand: #1d4ed8;
  --brand-soft: #eaf0ff;
  --accent: #0f766e;
  --accent-soft: #e3f5f2;
  --warn: #b45309;
  --danger: #b42318;
  --danger-soft: #fdecea;
  --ok: #15803d;
  --ok-soft: #e8f6ec;
  --radius: 14px;
  --shadow: 0 1px 2px rgba(20, 24, 31, .05), 0 12px 30px -18px rgba(20, 24, 31, .28);
  --mono: "SFMono-Regular", "JetBrains Mono", Menlo, Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 15px/1.65 "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Source Han Sans SC", "Noto Sans CJK SC", system-ui, sans-serif;
}

a { color: var(--brand); text-decoration: none; }
code { font-family: var(--mono); font-size: .88em; background: #f0f2f7; padding: 1px 5px; border-radius: 5px; word-break: break-all; }

/* ---------- 顶栏 ---------- */
.topbar {
  position: sticky; top: 0; z-index: 20;
  display: flex; align-items: center; gap: 18px; flex-wrap: wrap;
  padding: 12px clamp(14px, 4vw, 34px);
  background: rgba(255, 255, 255, .92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 11px; margin-right: auto; }
.brand strong { display: block; font-size: 15.5px; letter-spacing: .2px; }
.brand small { color: var(--muted); font-size: 11.5px; }
.logo {
  width: 34px; height: 34px; border-radius: 10px; flex: none;
  background: linear-gradient(135deg, var(--brand), #6d28d9);
  color: #fff; font-weight: 700; display: grid; place-items: center; font-size: 17px;
}
.nav { display: flex; gap: 4px; flex-wrap: wrap; }
.nav a {
  padding: 7px 13px; border-radius: 999px; color: var(--ink-2); font-size: 14px;
}
.nav a:hover { background: #eef1f7; }
.nav a.active { background: var(--brand); color: #fff; }
.backend {
  display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--ink-2);
  padding: 6px 11px; border: 1px solid var(--line); border-radius: 999px; background: #fff;
}
.backend .dot { width: 8px; height: 8px; border-radius: 50%; background: #9ca3af; flex: none; }
.backend.ok .dot { background: var(--ok); box-shadow: 0 0 0 3px var(--ok-soft); }
.backend.bad .dot { background: var(--danger); box-shadow: 0 0 0 3px var(--danger-soft); }

/* ---------- 版面 ---------- */
.page { max-width: 1180px; margin: 0 auto; padding: clamp(16px, 3vw, 30px) clamp(14px, 4vw, 34px) 60px; display: grid; gap: 18px; }
.card {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: clamp(16px, 2.4vw, 24px); box-shadow: var(--shadow);
}
.card + .card { margin-top: 0; }
.card h2, .card h3 { margin: 0 0 8px; line-height: 1.4; }
.card h2 { font-size: 19px; }
.card h3 { font-size: 16px; margin-top: 22px; }
.grid { display: grid; gap: 16px; }
.grid.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
