.state .msg { padding: 10px 13px; border-radius: 10px; border: 1px solid var(--line); background: #fafbfe; }
.state .msg.ok { background: var(--ok-soft); border-color: #bfe3c7; color: #14532d; }
.state .msg.err { background: var(--danger-soft); border-color: #f3c6c1; color: #7f1d1d; }
.state .msg.warn { background: #fef6e7; border-color: #f2dfae; color: #78350f; }
.badges { display: flex; gap: 8px; flex-wrap: wrap; }
.badge { font-size: 12px; padding: 4px 10px; border-radius: 999px; background: var(--brand-soft); color: var(--brand); font-weight: 600; }
.badge.teal { background: var(--accent-soft); color: var(--accent); }
.badge.grey { background: #eef1f6; color: var(--ink-2); }
.plan-head { display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap; margin-bottom: 6px; }

/* ---------- 首页 ---------- */
.modules { display: grid; gap: 8px; margin-top: 12px; }
