.kv { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 10px; margin: 10px 0 4px; }
.kv div { border: 1px solid var(--line); border-radius: 11px; padding: 11px 13px; background: #fcfdff; }
.kv dt, .kv .k { font-size: 12px; color: var(--muted); }
