.q-stem { margin: 0 0 12px; font-weight: 600; }
.options { display: grid; gap: 7px; }
.options label {
  flex-direction: row; align-items: flex-start; gap: 10px; font-size: 14.5px; color: var(--ink);
  border: 1px solid var(--line); border-radius: 10px; padding: 9px 12px; background: #fcfdff; cursor: pointer;
}
