.options input { width: auto; margin-top: 3px; flex: none; }
.explain { margin-top: 10px; font-size: 13.5px; color: var(--ink-2); background: #f6f8fc; border-left: 3px solid var(--brand); padding: 9px 12px; border-radius: 0 9px 9px 0; }
