async function refreshMemory() {
  const learnerId = CTX.learner.learner_id;
  const box = $("#memory-state");
  state(box, "", "正在从 PowerContext 读取该身份的记忆…");
  try {
    const kind = $("#filter-kind").value || undefined;
    const stateFilter = $("#filter-state").value || "active";
    const params = new URLSearchParams();
    if (kind) params.set("kind", kind);
    params.append("states", stateFilter);
    const data = await api(`/api/learners/${learnerId}/memories?${params.toString()}`);
    state(box, "ok", `Scope ${data.scope_id} · 共读回 ${data.entries.length} 条（筛选：kind=${kind || "全部"}，state=${stateFilter}）`);
    $("#scope-badge").textContent = `Scope ${data.scope_id}`;

    const overview = await api(`/api/learners/${learnerId}`);
    const stats = $("#memory-stats");
    stats.innerHTML = "";
    const weak = overview.topics.filter((row) => row.weak);
    [
      ["知识点覆盖", `${overview.topics.length} / ${(CTX.context.bank.modules || []).length}`, "已建立掌握记忆的知识点数量"],
      ["薄弱知识点", `${weak.length}`, weak.length ? weak.map((row) => row.name).join("、") : "暂无薄弱点"],
      ["最近一次安排", overview.last_plan ? `${overview.last_plan.mode} · ${overview.last_plan.question_ids.length} 题` : "尚无",
        overview.last_plan ? artifactLabel(overview.last_plan.artifact) : "答题后自动写入"],
    ].forEach(([title, value, note]) => {
      const card = el("div", "card");
      card.appendChild(el("div", "k muted small", title));
      card.appendChild(el("div", "v", String(value)));
      card.appendChild(el("div", "small muted", note));
      stats.appendChild(card);
    });

    $("#pref-count").value = overview.preference.daily_questions || 5;
    $("#pref-note").value = overview.preference.note || "";
    Array.from($("#pref-focus").options).forEach((option) => {
      option.selected = (overview.preference.focus_topics || []).includes(option.value);
    });

    renderMemoryTable(data.entries);
  } catch (error) {
    state(box, "err", describeError(error));
  }
}

function renderMemoryTable(entries) {
  const body = $("#memory-body");
  body.innerHTML = "";
  if (!entries.length) {
    const row = el("tr");
    const cell = el("td", "muted", "该筛选条件下没有记忆条目。真实读取结果为空，不会用示例数据填充。");
    cell.colSpan = 5;
    row.appendChild(cell);
    body.appendChild(row);
    return;
  }
  entries.forEach((entry) => {
    const tr = el("tr");
    tr.appendChild(pill(entry.kind, entry.kind));
    const content = el("td");
    const payload = entry.payload || {};
    content.appendChild(el("div", null, payload.summary || entry.text.slice(0, 160)));
    if (payload.topic) content.appendChild(el("div", "small muted", `知识点 ${payload.topic_name || payload.topic} · 掌握度 ${(payload.mastery ?? 0).toFixed(2)} · 连错 ${payload.wrong_streak ?? 0}`));
    content.appendChild(el("div", "id small", entry.text.length > 320 ? entry.text.slice(0, 320) + "…" : entry.text));
    tr.appendChild(content);
    tr.appendChild(el("td", "id", artifactLabel(entry.artifact)));
    tr.appendChild(pill(entry.state, entry.state));
    const actions = el("td");
    if (entry.state === "active") {
      const button = el("button", "mini", "遗忘");
      button.type = "button";
      button.onclick = () => forgetOne(entry);
      actions.appendChild(button);
    } else {
      actions.appendChild(el("span", "muted small", "已退出召回"));
    }
    tr.appendChild(actions);
    body.appendChild(tr);
  });
}

async function forgetOne(entry) {
  const box = $("#danger-state");
  const params = new URLSearchParams({ revision: String(entry.artifact.revision), state_version: String(entry.state_version) });
  state(box, "", "正在通过真实 lifecycle 接口遗忘该条记忆…");
  try {
    const receipt = await api(`/api/learners/${CTX.learner.learner_id}/memories/${entry.artifact.artifact_id}/forget?${params}`, { method: "POST" });
    state(box, "ok", `已遗忘 ${entry.artifact.artifact_id}（state=${receipt.state}, state_version=${receipt.state_version}）`);
    await refreshMemory();
  } catch (error) {
    state(box, "err", describeError(error));
  }
}

async function savePreference() {
  const box = $("#pref-state");
  const focus = Array.from($("#pref-focus").selectedOptions).map((option) => option.value);
  state(box, "", "正在写入 PowerContext…");
  try {
    const data = await api(`/api/learners/${CTX.learner.learner_id}/preference`, {
      method: "PUT",
      body: { daily_questions: Number($("#pref-count").value) || 5, focus_topics: focus, note: $("#pref-note").value.trim() },
    });
    state(box, "ok", `${data.text}　→　${artifactLabel(data.receipt.artifact)}`);
    await refreshMemory();
  } catch (error) {
    state(box, "err", describeError(error));
  }
}

async function forgetAll() {
  if (!confirm("确认清空该学习身份在 PowerContext 中的全部激活记忆？条目将置为 forgotten，历史仍可核验。")) return;
  const box = $("#danger-state");
  state(box, "", "正在逐条调用 lifecycle 接口遗忘…");
  try {
    const data = await api(`/api/learners/${CTX.learner.learner_id}/memories/forget-all`, { method: "POST" });
    state(box, "ok", `已遗忘 ${data.forgotten} 条记忆。`);
    await refreshMemory();
  } catch (error) {
    state(box, "err", describeError(error));
  }
}

async function runSearch() {
  const box = $("#search-result");
  box.textContent = "检索中…";
  try {
    const data = await api(`/api/learners/${CTX.learner.learner_id}/memories/search`, {
      method: "POST",
      body: { query: $("#search-query").value.trim() || "薄弱点", limit: 8 },
    });
    const lines = [`mode=${data.mode}（真实检索模式）　命中 ${data.hits.length} 条　耗时 ${data.duration_ms}ms`, ""];
    data.hits.forEach((hit) => {
      const payload = hit.payload || {};
      lines.push(`· ${artifactLabel(hit.artifact)}  kind=${hit.kind}  score=${hit.score.toFixed(5)}  matched_by=${hit.matched_by.join(",")}`);
      lines.push(`  ${payload.summary || hit.text.slice(0, 120)}`);
    });
    if (!data.hits.length) lines.push("（该 Scope 内没有匹配的激活记忆，返回真实空结果）");
    box.textContent = lines.join("\n");
  } catch (error) {
    box.textContent = describeError(error);
  }
}

async function runPrepare() {
  const box = $("#prepare-result");
  box.textContent = "生成中…";
  try {
    const data = await api(`/api/learners/${CTX.learner.learner_id}/memories/prepare`, {
