/* 拾忆 · Recall Coach 前端：全部数据来自本机服务端接口，服务端再调用真实 PowerContext。 */
"use strict";

const CTX = { context: null, session: null, learner: null };
const LS_KEY = "recall.learner";
const KIND_LABEL = { weakness: "薄弱点", progress: "掌握变化", preference: "复习偏好", plan: "复习安排" };

/* ---------------- 基础工具 ---------------- */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

function el(tag, cls, text) {
  const node = document.createElement(tag);
  if (cls) node.className = cls;
  if (text !== undefined) node.textContent = text;
  return node;
}

async function api(path, options = {}) {
  const response = await fetch(path, {
    headers: { "Content-Type": "application/json" },
    ...options,
    body: options.body ? JSON.stringify(options.body) : undefined,
  });
  let data = null;
  try { data = await response.json(); } catch (_) { data = null; }
  if (!response.ok) {
    const error = new Error((data && data.error && data.error.message) || `请求失败（HTTP ${response.status}）`);
    error.payload = data;
    error.status = response.status;
    throw error;
  }
  return data;
}

function state(node, kind, text) {
  node.className = "state";
  node.innerHTML = "";
  if (!text) return;
  node.appendChild(el("div", `msg ${kind || ""}`, text));
}

function artifactLabel(artifact) {
  return `${artifact.family}/${artifact.artifact_id}@${artifact.revision}`;
}

function pill(text, cls) {
  return el("span", `pill ${cls || text}`, text);
}

function describeError(error) {
  const payload = error.payload && error.payload.error;
  if (!payload) return error.message;
  const parts = [payload.message];
  if (payload.code) parts.push(`错误码 ${payload.code}`);
  if (payload.operation) parts.push(`操作 ${payload.operation}`);
  if (payload.request_id) parts.push(`request-id ${payload.request_id}`);
  if (payload.status_code) parts.push(`HTTP ${payload.status_code}`);
  return parts.join("　·　");
}

/* ---------------- 顶栏状态 ---------------- */
async function loadContext(force = false) {
  if (CTX.context && !force) return CTX.context;
  try {
    CTX.context = await api("/api/context");
    return CTX.context;
  } catch (error) {
    CTX.context = null;
    const pill = $("#backend-pill");
    pill.classList.remove("ok");
    pill.classList.add("bad");
    const payload = error.payload && error.payload.error;
    $("#backend-text").textContent = payload
      ? `PowerContext 不可用：${payload.code}`
      : "无法连接本项目后端，请先执行 scripts/start_app.sh";
    throw error;
  }
}

function paintBackend(context) {
  const pill = $("#backend-pill");
  pill.classList.remove("bad");
  pill.classList.add("ok");
  const modes = (context.powercontext.search_modes || []).join("/");
  $("#backend-text").textContent = `PowerContext 已就绪 · ${context.powercontext.base_url} · 检索 ${modes}`;
}

/* ---------------- 概览页 ---------------- */
