    ["服务地址", backend.base_url],
    ["健康检查 /health/ready", backend.health.status],
    ["可用检索模式", (backend.search_modes || []).join("、")],
    ["自动抽取（需模型）", backend.memory_extraction ? "已启用" : "未配置：如实关闭"],
    ["证据类型", (backend.source_types || []).join("、")],
    ["上下文版本", (backend.context_versions || []).join("、")],
